const VERIFY_TOKEN = process.env.META_VERIFY_TOKEN || 'REPLACE_WITH_RANDOM_VERIFY_TOKEN';
const q = $json.query || {};
const mode = q['hub.mode'] ?? q['hub_mode'];
const token = q['hub.verify_token'] ?? q['hub_verify_token'];
const challenge = q['hub.challenge'] ?? q['hub_challenge'];
const ok = mode === 'subscribe' && token === VERIFY_TOKEN && typeof challenge === 'string';
return [{ json: { status: ok ? 200 : 403, challenge: ok ? challenge : 'Forbidden' } }];

const crypto = require('crypto');
const APP_SECRET = process.env.META_APP_SECRET || 'REPLACE_WITH_META_APP_SECRET';
const GUIDE_URL = 'https://github.com/MrABFlow/instagram-comment-to-dm-diy/blob/main/SETUP.md';
const API_VERSION = 'v26.0'; // Verify the currently supported version before production.
const headers = $json.headers || {};
const signature = headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'] || '';
const rawValue = $json.rawBody;
let raw;
if (typeof rawValue === 'string') raw = Buffer.from(rawValue, 'utf8');
else if (Buffer.isBuffer(rawValue)) raw = rawValue;
else if (rawValue && Array.isArray(rawValue.data)) raw = Buffer.from(rawValue.data);
else if (rawValue && typeof rawValue === 'object' && typeof rawValue.toString === 'function') raw = Buffer.from(rawValue.toString(), 'utf8');
const expected = raw && APP_SECRET !== 'REPLACE_WITH_META_APP_SECRET' ? 'sha256=' + crypto.createHmac('sha256', APP_SECRET).update(raw).digest('hex') : '';
let valid = false;
if (expected && typeof signature === 'string' && signature.length === expected.length) valid = crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
if (!valid) return [{ json: { status: 403, process: false, message: 'Invalid webhook signature' } }];
if (!GUIDE_URL.startsWith('https://') || GUIDE_URL.includes('REPLACE_WITH')) return [{ json: { status: 200, process: false, message: 'Set GUIDE_URL in this Code node before launch' } }];
let body = $json.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { return [{ json: { status: 400, process: false, message: 'Invalid JSON' } }]; } }
if (!body || !Array.isArray(body.entry)) return [{ json: { status: 200, process: false, message: 'No Instagram entries' } }];
const actions = [];
for (const entry of body.entry) {
  const igUserId = entry.id;
  for (const change of (entry.changes || [])) {
    if (change.field !== 'comments') continue;
    const c = change.value || {};
    const text = String(c.text || '').trim();
    if (text.toUpperCase() !== 'AUTOMATE' || !c.id || !igUserId) continue;
    if (c.from && String(c.from.id) === String(igUserId)) continue;
    actions.push({ json: { status: 200, process: true, commentId: String(c.id), apiUrl: `https://graph.instagram.com/${API_VERSION}/${encodeURIComponent(String(igUserId))}/messages`, apiPayload: { recipient: { comment_id: String(c.id) }, message: { text: `Here’s the setup: ${GUIDE_URL}` } } });
  }
}
return actions.length ? actions : [{ json: { status: 200, process: false, message: 'No matching AUTOMATE comments' } }];
